        return;
    }
    const script = __dirname + '/app.js';
    const name = 'pingan-vue-floating-server-ap'
    const pm2Options = {
        script,
        name,
        exec_mode: 'cluster',
        daemon: true
    };
    pm2.start(pm2Options, (err, apps) => {
        if (err) {
            pm2.disconnect();
        } else {
            pm2.disconnect();
        }
    });
});
